#include "ksPartRouteTask.h"
#include <iostream>
#include <stdexcept>
static void check(bool b){if(!b)throw std::runtime_error("Part route property failed");}
int main(){using T=ks::PartRouteTask;uint64_t cases=0;for(unsigned kind=0;kind<2;++kind)for(unsigned level=0;level<256;++level)for(unsigned mode=0;mode<256;++mode){T t{T::Kind(kind)};unsigned controls=0,routes=0,modes=0,lows=0,highs=0,writes=0,guard=0;auto input=uint8_t(level^mode),firstPart=uint8_t(level),lastPart=uint8_t(mode);auto read=[&](T::Read r)->uint32_t{return r==T::Read::Input?input:r==T::Read::Level?level:mode;};auto write=[&](uint8_t v){check(kind==0&&v==input&&t.part()==firstPart);++writes;};auto store=[](){return 3;};while(t.stage()!=T::Stage::Complete){check(++guard<48);auto child=t.child();if(child!=T::Child::None){uint8_t part=0;if(child==T::Child::Control){++controls;part=(kind==0&&controls==1)?firstPart:lastPart;}if(child==T::Child::Route)++routes;if(child==T::Child::Mode){check(t.code()==(mode<2?mode*2:(mode-2)&254)&&t.part()==lastPart);++modes;}if(child==T::Child::Low){check(t.low()==((mode<2||!(mode&1))?level:0));++lows;}if(child==T::Child::High){check(t.high()==((mode<2||(mode&1))?level:0));++highs;}check(t.resumeChild(part));continue;}auto c=t.nextClocks(store),s=unsigned(t.stage());check(t.advanceBefore(c-1,read,write,store)==0&&unsigned(t.stage())==s);check(t.advanceBefore(c,read,write,store)==c);}check(controls==(kind?1:2)&&routes==unsigned(!kind)&&writes==unsigned(!kind)&&modes==1&&lows==1&&highs==1);++cases;}std::cout<<"PASS: "<<cases<<" pure part route properties; both kinds/all level-mode pairs, new part binding after route, independent input write, exact low/high split,3 ordered packets and budget refusal\n";}
